css:
.ab_sec-h{position:relative;z-index:3;display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-end;grid-row-gap:20px;grid-column-gap:40px;margin-bottom:clamp(28px,4vw,48px)}
.ab_section-head.is-flush{margin-bottom:0}
.ab_sec-h_lede{max-width:44ch;color:var(--_color---text--secondary)}
.section_monitor{position:relative}
.ab_mc{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,1fr) 280px;grid-row-gap:18px;grid-column-gap:18px}
.ab_mon{position:relative;min-width:0;padding-top:12px;padding-right:12px;padding-bottom:12px;padding-left:12px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair-strong);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair-strong);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair-strong);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair-strong);background-image:linear-gradient(#171a28,#0c0e17);box-shadow:0 40px 90px -40px rgba(0,0,0,0.9),inset 0 1px 0 rgba(255,255,255,0.06)}
.ab_mon_bar{display:flex;justify-content:space-between;align-items:center;grid-row-gap:12px;grid-column-gap:12px;padding-top:2px;padding-right:10px;padding-bottom:10px;padding-left:10px;color:var(--_color---text--tertiary)}
.ab_mon_rec{display:inline-flex;align-items:center;grid-row-gap:7px;grid-column-gap:7px;color:#ff4b3a}
.ab_mon_tc{color:var(--_color---text--secondary)}
.ab_screen{position:relative;aspect-ratio:16/10;overflow-x:hidden;overflow-y:hidden;isolation:isolate;background-color:#05060a}
.ab_mon_cap{display:flex;justify-content:space-between;grid-row-gap:16px;grid-column-gap:16px;min-height:46px;padding-top:12px;padding-right:10px;padding-bottom:2px;padding-left:10px;color:var(--_color---text--secondary);font-size:14px}
.ab_mon_kind{color:var(--_color---text--tertiary);white-space:nowrap}
.ab_console{display:flex;flex-direction:column;grid-row-gap:14px;grid-column-gap:14px;min-width:0}
.ab_panel{padding-top:14px;padding-right:14px;padding-bottom:14px;padding-left:14px;border-top-width:1px;border-top-style:solid;border-top-color:var(--_color---neutral--hair);border-right-width:1px;border-right-style:solid;border-right-color:var(--_color---neutral--hair);border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--_color---neutral--hair);border-left-width:1px;border-left-style:solid;border-left-color:var(--_color---neutral--hair);background-color:rgba(14,16,32,0.88)}
.ab_panel_h{display:flex;justify-content:space-between;margin-bottom:10px;color:var(--_color---text--tertiary);text-transform:uppercase;letter-spacing:0.12em}
.ab_chans{display:flex;flex-direction:column;grid-row-gap:4px;grid-column-gap:4px}
.ab_tele{display:grid;grid-template-columns:1fr 1fr;grid-row-gap:10px;grid-column-gap:10px}
.ab_tele_item{display:flex;flex-direction:column;grid-row-gap:3px;grid-column-gap:3px}
.ab_tele_k{font-size:10px;letter-spacing:0.1em;text-transform:uppercase;color:var(--_color---text--tertiary)}
.ab_tele_v{font-size:15px;font-weight:500;color:var(--_color---text--primary)}
.ab_tele_v.is-ok{color:#3BE38A}
.ab_tele_ok{color:#3BE38A}
.button.is-ghost.is-full{width:100%}
@media screen and (max-width: 991px) {
.ab_mc{grid-template-columns:minmax(0,1fr)}
.ab_console{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media screen and (max-width: 479px) {
.ab_console{grid-template-columns:minmax(0,1fr)}
.ab_screen{aspect-ratio:4/5}
.ab_mon_cap{flex-direction:column;grid-row-gap:4px;grid-column-gap:4px}
}
